import itertools, json
Aopts=['KMP','LNP','KLN','MQR','LMQ']
Bopts=['LPQ','NPR','LMP','MNR','KNP']
Adays=[{2,7},{1,6,7},{7},{8},{2,7}]
Bdays=[{4,6},{3},{2,8},{3},{6,7,8}]
people=set('KLMNPQR'); west=set('KPR')
As=[x for x in itertools.product(*Aopts) if len(set(x))==5]
Bs=[x for x in itertools.product(*Bopts) if len(set(x))==5]
count=0; hist={}; witnesses={}
for a in As:
 for b in Bs:
  both=set(a)&set(b)
  if len(both)!=3 or len(both&west)!=1: continue
  days={p:set() for p in people}
  for ids, ds in [(a,Adays),(b,Bdays)]:
   for p,d in zip(ids,ds): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  count+=1; hist[n]=hist.get(n,0)+1
  witnesses.setdefault(n, {'A':''.join(a),'B':''.join(b)})
lo=min(hist); hi=max(hist)
result={'feasible_linkages':count,'bounds':[lo,hi],'low_witness':witnesses[lo],'high_witness':witnesses[hi],'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
print(json.dumps({'result':result,'histogram':hist,'A_count':len(As),'B_count':len(Bs)}))

